        "factor": "Policy/regulatory crackdown reducing search-and-rescue capacity",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Reduced SAR capacity can raise mortality risk, adding modest upward pressure on the tally."
      },
      {
        "factor": "Surge in departures from Libya/Tunisia increasing exposure",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "More departures raise exposure and potential fatalities, providing incremental upward pressure."
      },
      {
        "factor": "Lack of March-specific forecast models; uncertainty about March outcome",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Absence of March-specific models adds calibration uncertainty and limits precise projection, weighting minorly in the final estimate."
      }
